enum class FfiAggFunc {
    
    /**
     * Number of rows (no column).
     */
    COUNT,
    /**
     * Number of rows where the column is non-null.
     */
    COUNT_COLUMN,
    SUM,
    MIN,
    MAX,
    AVG;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeFfiAggFunc: FfiConverterRustBuffer<FfiAggFunc> {
    override fun read(buf: ByteBuffer) = try {
        FfiAggFunc.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: FfiAggFunc) = 4UL

    override fun write(value: FfiAggFunc, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







sealed class FfiBknException: kotlin.Exception() {
    
    class Backend(
        
        val `message`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "message=${ `message` }"
    }
    
    class TableNotFound(
        
        val `table`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "table=${ `table` }"
    }
    
    class NotFound(
        ) : FfiBknException() {
        override val message
            get() = ""
    }
    
    class Encoding(
        
        val `message`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "message=${ `message` }"
    }
    
    class ReservedTableName(
        
        val `table`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "table=${ `table` }"
    }
    
    class DatabaseLocked(
        
        val `path`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "path=${ `path` }"
    }
    
    class DuplicateKey(
        
        val `table`: kotlin.String, 
        
        val `key`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "table=${ `table` }, key=${ `key` }"
    }
    
    class SchemaMismatch(
        
        val `table`: kotlin.String, 
        
        val `message`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "table=${ `table` }, message=${ `message` }"
    }
    
    class ConstraintViolation(
        
        val `table`: kotlin.String, 
        
        val `message`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "table=${ `table` }, message=${ `message` }"
    }
    
    class Corruption(
        
        val `message`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "message=${ `message` }"
    }
    
    class InvalidQuery(
        
        val `message`: kotlin.String
        ) : FfiBknException() {
        override val message
            get() = "message=${ `message` }"
    }
    
    class DatabaseClosed(
        ) : FfiBknException() {
        override val message
            get() = ""
    }
    
    class TransactionInProgress(
        ) : FfiBknException() {
        override val message
            get() = ""
    }
    
    class TransactionClosed(
